_choice_c() {
    if [[ -n "$argc__option" ]]; then
        local -n ref="$argc__option"
        argc__positionals=( "${ref[@]}" )
        unset -n ref
    fi
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 0
    fi
}

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_option() {
    local prefix=""
    [[ "${argc__option:-}" == "argc_no" ]] && prefix="-"
    zsh --help 2>/dev/null | gawk -v prefix="$prefix" '
        /^(Named options:|Option aliases:)/ { section = 1; next }
        section && /^[[:space:]]*--/ {
            name = $1
            sub(/^--/, "", name)
            if (NF > 1) {
                desc = $0
                sub(/^[[:space:]]+/, "", desc)
                sub(/^[^[:space:]]+[[:space:]]+/, "", desc)
                printf "%s%s\t%s\n", prefix, name, desc
            } else {
                printf "%s%s\n", prefix, name
            }
            next
        }
        section && /^[^[:space:]]/ { section = 0 }
    '
}
